					>
						<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
						<polyline points="7 10 12 15 17 10" />
						<line x1="12" y1="15" x2="12" y2="3" />
					</svg>
					{{ memuatPdf ? 'Memuat…' : 'Download PDF' }}
				</button>
				<button
					v-if="data?.aksi?.length"
					type="button"
					:disabled="!!menjalankan"
					class="flex flex-1 items-center justify-center gap-2 rounded-full bg-primary py-3 text-sm font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.99] disabled:opacity-50"
					@click="actionsOpen = true"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-4 w-4"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<circle cx="12" cy="12" r="1" />
						<circle cx="19" cy="12" r="1" />
						<circle cx="5" cy="12" r="1" />
					</svg>
					{{ menjalankan ? `Memproses “${menjalankan}”…` : 'Actions' }}
				</button>
			</div>
		</div>

		<!-- ====== Bottom-sheet Actions (transisi workflow) ====== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
