								<button
									v-for="a in data.aksi"
									:key="`${a.action}|${a.next_state}`"
									type="button"
									:disabled="!!menjalankan"
									class="flex w-full items-center justify-between gap-2 rounded-2xl border border-ui-line-gray-200 px-4 py-3.5 text-left transition hover:border-primary hover:bg-primary/5 disabled:opacity-50"
									@click="pilihAksi(a.action)"
								>
									<span class="text-sm font-semibold text-ui-ink-gray-800">{{
										a.action
									}}</span>
									<span class="shrink-0 text-xs text-ui-ink-gray-400"
