</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { refreshCsrfToken } from '../data/session'
import { brokerPillClass, pesanKonfirmasi } from '../data/requestBrokerStatus'
import { notifyError, notifySuccess } from '../composables/toast'
import { openPdf } from '../composables/pdfViewer'
import { useBackNavigation } from '../composables/useBackNavigation'

const API = '/api/method/juragan.api.portal.request_broker'

const route = useRoute()
const { backTarget, backLabel } = useBackNavigation({ name: 'RequestBroker' }, 'Request Broker')
const name = computed(() => route.params.name)

const data = ref(null)
const loading = ref(false)
const error = ref('')
const menjalankan = ref('')
const actionsOpen = ref(false)
const konfirmasi = reactive({ aksi: '', pesan: '' })

function pesanError(json, res) {
	try {
		if (json && json._server_messages) {
			return JSON.parse(json._server_messages)
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* abaikan */
	}
	return (json && (json.exception || json.message)) || `HTTP ${res.status}`
}

async function muat() {
	loading.value = true
	error.value = ''
	try {
		const params = new URLSearchParams({ name: name.value })
		const res = await fetch(`${API}.get_detail?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(pesanError(json, res))
		data.value = json.message
	} catch (e) {
		error.value = e.message || String(e)
	} finally {
		loading.value = false
	}
}

const grupData = computed(() => {
	const d = data.value || {}
	// Urutan sama dengan form (Tipe Broker tampil sebagai chip di ringkasan).
	return [
		{
			judul: 'Data Broker',
			isi: [
				{ label: 'NIK', value: d.nik },
				{ label: 'Nama Sesuai KTP', value: d.nama_pemilik },
				{ label: 'Nama Broker', value: d.nama_mokas },
				{ label: 'No NPWP', value: d.no_npwp },
				{ label: 'No HP', value: d.no_hp },
				{ label: 'Alamat', value: d.alamat_mokas },
			],
		},
		{
			judul: 'Rekening',
			isi: [
				{ label: 'Nama Bank', value: d.nama_bank },
				{ label: 'Nomor Rekening', value: d.nomor_rekening },
			],
		},
	]
})

function labelTipe(tipe) {
	return tipe === 'EndUser' ? 'End User' : tipe || ''
}

// Timeline: Diajukan → tiap persetujuan/penolakan → (masih menunggu). Nama saja,
// tanpa jabatan; label tahap sama dengan desk.
const riwayat = computed(() => {
	const d = data.value || {}
	const hijau = 'bg-ui-ink-green-600'
	const baris = (label, nama, waktu, warna = hijau) => ({
		label,
		keterangan: [nama, waktu].filter(Boolean).join(' · '),
		warna,
	})
	const r = []
	if (d.status === 'Draft') {
		r.push(baris('Draft', 'Belum diajukan', '', 'bg-ui-ink-gray-400'))
		return r
	}
	r.push(
		baris(
			'Diajukan',
			d.nama_pengaju || d.diajukan_oleh,
			d.tanggal_pengajuan && formatTanggal(d.tanggal_pengajuan)
		)
	)
	if (d.disetujui_pincab_oleh)
		r.push(
			baris(
				'Direkomendasikan',
				d.disetujui_pincab_oleh_nama,
				formatWaktu(d.waktu_approval_pincab)
			)
		)
	if (d.disetujui_mo_oleh)
		r.push(baris('Disetujui', d.disetujui_mo_oleh_nama, formatWaktu(d.waktu_approval_mo)))
	if (d.disetujui_direktur_oleh)
		r.push(
			baris(
				'Disetujui Akhir',
				d.disetujui_direktur_oleh_nama,
				formatWaktu(d.waktu_approval_direktur)
			)
		)
	if (d.ditolak_oleh)
		r.push(
			baris(
				'Ditolak',
				d.ditolak_oleh_nama,
				formatWaktu(d.waktu_ditolak),
				'bg-ui-ink-red-600'
			)
		)
	if (String(d.status || '').startsWith('Menunggu'))
		r.push(baris('Menunggu persetujuan', '', '', 'bg-ui-ink-amber-500'))
	return r
})

function kelasTombol(aksi) {
	if (aksi === 'Reject') return 'bg-ui-surface-red-600 text-white hover:bg-ui-surface-red-700'
	return 'bg-primary text-ui-onPrimary hover:bg-primary/90'
}

// Pilih aksi dari bottom-sheet Actions → tutup sheet, lalu minta konfirmasi.
function pilihAksi(aksi) {
	actionsOpen.value = false
	mintaKonfirmasi(aksi)
}

function mintaKonfirmasi(aksi) {
	konfirmasi.aksi = aksi
	konfirmasi.pesan = pesanKonfirmasi(aksi, data.value?.status, data.value?.tipe_broker)
}
function tutupKonfirmasi() {
	konfirmasi.aksi = ''
	konfirmasi.pesan = ''
}

async function jalankan() {
	const aksi = konfirmasi.aksi
	tutupKonfirmasi()
	menjalankan.value = aksi
	try {
		const res = await fetch(`${API}.jalankan_aksi`, {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ name: name.value, action: aksi }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(pesanError(json, res))
		data.value = json.message
		const status = data.value?.status
		if (aksi === 'Reject') notifySuccess(`Request ${name.value} ditolak.`)
		else if (status === 'Approved')
			notifySuccess(`Request ${name.value} di-approve. Data Mokas sudah dibuat.`)
		else if (aksi === 'Ajukan Approval')
			notifySuccess(`Request ${name.value} diajukan. Status: ${status}`)
		else notifySuccess(`Request ${name.value} di-approve. Status: ${status}`)
	} catch (e) {
		notifyError(e, `Gagal menjalankan "${aksi}"`)
	} finally {
		menjalankan.value = ''
	}
}

function bukaPdf() {
	openPdf(data.value.file_dokumen, `Dokumen ${name.value}`)
}

// Form pendaftaran ber-QR dibuat doc_signer di background saat Approved, jadi
// diambil ulang saat tombol diketuk (bisa saja baru jadi setelah halaman dibuka).
const bisaDownloadPdf = computed(() => data.value?.status === 'Approved')
const adaBarBawah = computed(() => bisaDownloadPdf.value || !!data.value?.aksi?.length)
const memuatPdf = ref(false)

async function downloadFormPdf() {
	if (memuatPdf.value) return
	memuatPdf.value = true
	try {
		let fileUrl = data.value?.form_pdf || ''
		if (!fileUrl) {
			const params = new URLSearchParams({
				reference_doctype: 'Request Pendaftaran Broker',
				reference_name: name.value,
			})
			const res = await fetch(
				`/api/method/juragan.juragan.doctype.document_signing_log.document_signing_log.get_latest_signed_pdf?${params.toString()}`,
				{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
			)
			if (res.ok) fileUrl = (await res.json().catch(() => ({})))?.message || ''
		}
		if (!fileUrl) throw new Error('Form PDF sedang dibuat. Coba lagi beberapa saat.')
		data.value.form_pdf = fileUrl
		openPdf(fileUrl, `Form Pendaftaran Broker ${name.value}`)
	} catch (e) {
		notifyError(e, 'Gagal membuka PDF')
	} finally {
		memuatPdf.value = false
	}
}

function namaFile(url) {
	return String(url || '')
		.split('/')
		.pop()
}
function formatTanggal(v) {
	if (!v) return '—'
	const d = new Date(String(v).replace(' ', 'T'))
	if (Number.isNaN(d.getTime())) return String(v)
	return d.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
}
function formatWaktu(v) {
	if (!v) return '—'
	const d = new Date(String(v).replace(' ', 'T'))
	if (Number.isNaN(d.getTime())) return String(v)
	return d.toLocaleString('id-ID', {
		day: '2-digit',
		month: 'short',
		year: 'numeric',
		hour: '2-digit',
		minute: '2-digit',
	})
}

onMounted(async () => {
	await refreshCsrfToken()
	muat()
})
</script>
